#!/usr/bin/env bash
# P6 lab: generate the backup lab credentials into the gitignored .lab/backup/ (idempotent: existing values are
# kept). LAB ONLY — production credentials are generated by the Center (repo passwords) and the operator.
#
#   .lab/backup/htpasswd             rest-server users for lab-backup (one per lab server: node-a, node-b; bcrypt)
#   .lab/backup/admin-htpasswd       the maintenance identity for lab-backup-admin (user `admin`; bcrypt)
#   .lab/backup/servers/<user>.env   PPANEL_LAB_BK_USER / _REST_PASSWORD / _REPO_PASSWORD (what the Center would
#                                    deliver via the job secrets call: restic.{restUser,restPassword,repoPassword})
#   .lab/backup/admin.env            PPANEL_BACKUP_ADMIN_USER / PPANEL_BACKUP_ADMIN_PASSWORD (maintenance.sh)
#   .lab/backup/minio.env            MINIO_ROOT_USER / MINIO_ROOT_PASSWORD (lab-minio env_file)
#
#   scripts/lab/backup-secrets.sh            generate (before `compose up`; called by up.sh)
#   scripts/lab/backup-secrets.sh --bucket   create the offsite bucket in lab-minio (after up; called by up.sh)
# Secret values never appear in argv: htpasswd reads the password from stdin, mc gets MC_HOST_* via env.
# shellcheck source=scripts/lab/_common.sh
source "$(dirname "${BASH_SOURCE[0]}")/_common.sh"

BK="${PPANEL_LAB_BACKUP_DIR:-${REPO_ROOT}/.lab/backup}"
REST_SERVER_IMAGE="restic/rest-server:0.14.0@sha256:d2aff06f47eb38637dff580c3e6bce4af98f386c396a25d32eb6727ec96214a5"
LAB_BK_USERS=(node-a node-b)
OFFSITE_BUCKET="ppanel-offsite"

rand() { openssl rand -hex 24; }

# bcrypt line "user:hash" with the password on stdin (never argv)
htline() {
  local user="$1" pw="$2"
  printf '%s' "${pw}" | docker run --rm -i --network none --entrypoint htpasswd "${REST_SERVER_IMAGE}" -niB "${user}" | tr -d '\r' | head -1
}

if [[ "${1:-}" == "--bucket" ]]; then
  # shellcheck disable=SC1091
  source "${BK}/minio.env"
  export MC_HOST_local="http://${MINIO_ROOT_USER}:${MINIO_ROOT_PASSWORD}@127.0.0.1:9000"
  for _ in $(seq 1 30); do
    docker exec -e MC_HOST_local ppanel-lab-minio mc ready local >/dev/null 2>&1 && break
    sleep 1
  done
  docker exec -e MC_HOST_local ppanel-lab-minio mc mb --ignore-existing "local/${OFFSITE_BUCKET}" >/dev/null
  log "lab-minio bucket ${OFFSITE_BUCKET} present"
  exit 0
fi

umask 077
mkdir -p "${BK}/servers"
chmod 0700 "${BK}" "${BK}/servers"

for u in "${LAB_BK_USERS[@]}"; do
  f="${BK}/servers/${u}.env"
  if [[ ! -s "${f}" ]]; then
    printf 'PPANEL_LAB_BK_USER=%s\nPPANEL_LAB_BK_REST_PASSWORD=%s\nPPANEL_LAB_BK_REPO_PASSWORD=%s\n' "${u}" "$(rand)" "$(rand)" >"${f}"
    log "generated ${f}"
  fi
done
if [[ ! -s "${BK}/admin.env" ]]; then
  printf 'PPANEL_BACKUP_ADMIN_USER=admin\nPPANEL_BACKUP_ADMIN_PASSWORD=%s\n' "$(rand)" >"${BK}/admin.env"
  log "generated ${BK}/admin.env"
fi
if [[ ! -s "${BK}/minio.env" ]]; then
  printf 'MINIO_ROOT_USER=ppanel-lab\nMINIO_ROOT_PASSWORD=%s\n' "$(rand)" >"${BK}/minio.env"
  log "generated ${BK}/minio.env"
fi

# (re)build the htpasswd files from the env files whenever an env file is newer
need=0
[[ -s "${BK}/htpasswd" && -s "${BK}/admin-htpasswd" ]] || need=1
for f in "${BK}"/servers/*.env "${BK}/admin.env"; do
  [[ "${f}" -nt "${BK}/htpasswd" ]] && need=1
done
if [[ "${need}" == 1 ]]; then
  tmp="$(mktemp "${BK}/htpasswd.XXXX")"
  for u in "${LAB_BK_USERS[@]}"; do
    pw="$(sed -n 's/^PPANEL_LAB_BK_REST_PASSWORD=//p' "${BK}/servers/${u}.env")"
    htline "${u}" "${pw}" >>"${tmp}"
  done
  apw="$(sed -n 's/^PPANEL_BACKUP_ADMIN_PASSWORD=//p' "${BK}/admin.env")"
  atmp="$(mktemp "${BK}/admin-htpasswd.XXXX")"
  htline admin "${apw}" >"${atmp}"
  # bcrypt hashes only; world-readable so the rest-server containers (root without DAC caps) can read the bind mount
  chmod 0644 "${tmp}" "${atmp}"
  # keep the inode stable for running containers (bind-mounted files)
  if [[ -f "${BK}/htpasswd" ]]; then cat "${tmp}" >"${BK}/htpasswd"; rm -f "${tmp}"; else mv "${tmp}" "${BK}/htpasswd"; fi
  if [[ -f "${BK}/admin-htpasswd" ]]; then cat "${atmp}" >"${BK}/admin-htpasswd"; rm -f "${atmp}"; else mv "${atmp}" "${BK}/admin-htpasswd"; fi
  log "wrote ${BK}/htpasswd (${LAB_BK_USERS[*]}) and ${BK}/admin-htpasswd (admin)"
fi
